def banner(text):
    print("\n" + "=" * 110)
    print(text)
    print("=" * 110)


def save_plot(name):
    path = PLOT_DIR / f"{name}.png"
    plt.tight_layout()
    plt.savefig(path, dpi=180, bbox_inches="tight")
    if SHOW_PLOTS:
        plt.show()
    plt.close()
    print(f"[PLOT] {path}")


def decode_object_columns(df):
    out = df.copy()
    for c in out.columns:
        if out[c].dtype == "object":
            out[c] = out[c].map(lambda v: v.decode("utf-8", errors="ignore") if isinstance(v, (bytes, bytearray)) else str(v))
    return out


def load_real_dataset():
    banner("DATASET DOWNLOAD AND CONTEXTUAL PREPROCESSING")
    try:
        bunch = fetch_kddcup99(percent10=True, shuffle=True, random_state=SEED, as_frame=True)
        X_raw = decode_object_columns(bunch.data)
        if X_raw.shape[1] == 41 and not {"protocol_type", "service", "flag"}.issubset(set(X_raw.columns)):
            X_raw.columns = KDD_COLUMNS
        target = pd.Series(bunch.target).map(
            lambda v: v.decode("utf-8", errors="ignore") if isinstance(v, (bytes, bytearray)) else str(v)
        )
        print("Dataset source: sklearn.datasets.fetch_kddcup99 (KDD Cup 1999, 10% subset)")
    except Exception as e:
        print(f"Primary download failed: {e}")
        url = "https://kdd.ics.uci.edu/databases/kddcup99/kddcup.data_10_percent.gz"
        df = pd.read_csv(url, names=KDD_COLUMNS + ["target"], compression="gzip", low_memory=False)
        X_raw = decode_object_columns(df[KDD_COLUMNS])
        target = df["target"].astype(str)
        print("Dataset source: official UCI KDD Archive direct download")

    y = (target.str.strip() != "normal.").astype(np.int32).to_numpy()
    attack_type = target.str.strip().str.rstrip(".")

    if len(X_raw) > MAX_SAMPLES:
        idx_all = np.arange(len(X_raw))
        idx_sample, _ = train_test_split(
            idx_all, train_size=MAX_SAMPLES, stratify=y, random_state=SEED
        )
        X_raw = X_raw.iloc[idx_sample].reset_index(drop=True)
        y = y[idx_sample]
        attack_type = attack_type.iloc[idx_sample].reset_index(drop=True)

    print(f"Working samples: {len(X_raw):,}")
    print(f"Raw attributes: {X_raw.shape[1]}")
    print(f"Normal samples: {(y == 0).sum():,}")
    print(f"Intrusion samples: {(y == 1).sum():,}")
    print("Most frequent contextual traffic labels:")
    print(attack_type.value_counts().head(12).to_string())

    context = X_raw.copy()
    context["attack_type"] = attack_type
    context["binary_label"] = y
    context.sample(min(3000, len(context)), random_state=SEED).to_csv(
        OUTPUT_DIR / "dataset_contextual_samples.csv", index=False
    )
    return X_raw, y, attack_type


def build_preprocessor(X_train_raw):
    categorical = [c for c in ["protocol_type", "service", "flag"] if c in X_train_raw.columns]
    numeric = [c for c in X_train_raw.columns if c not in categorical]
    for c in numeric:
        X_train_raw[c] = pd.to_numeric(X_train_raw[c], errors="coerce").fillna(0.0)
    try:
        encoder = OneHotEncoder(handle_unknown="ignore", sparse_output=False)
    except TypeError:
        encoder = OneHotEncoder(handle_unknown="ignore", sparse=False)
    preprocessor = ColumnTransformer([
        ("num", StandardScaler(), numeric),
        ("cat", encoder, categorical)
    ])
    return preprocessor, numeric, categorical


def safe_numeric(df, name):
    if name not in df.columns:
        return np.zeros(len(df), dtype=np.float32)
    return pd.to_numeric(df[name], errors="coerce").fillna(0.0).to_numpy(dtype=np.float32)


def sigmoid_np(x):
    x = np.clip(x, -40, 40)
    return 1.0 / (1.0 + np.exp(-x))


def minmax_1d(x):
    x = np.asarray(x, dtype=np.float64)
    lo, hi = np.nanmin(x), np.nanmax(x)
    if hi - lo < 1e-12:
        return np.zeros_like(x)
    return (x - lo) / (hi - lo)


def calculate_entropy_column(x, bins=20):
    hist, _ = np.histogram(x, bins=bins)
    p = hist.astype(np.float64)
    p = p[p > 0]
    p /= p.sum()
    return float(-(p * np.log2(p + 1e-12)).sum())


def metric_row(stage, y_true, probabilities, latency_ms=0.0, threshold=0.5, extra=None):
    p = np.clip(np.asarray(probabilities).reshape(-1), 1e-7, 1 - 1e-7)
    pred = (p >= threshold).astype(int)
    cm = confusion_matrix(y_true, pred, labels=[0, 1])
    tn, fp, fn, tp = cm.ravel()
    row = {
        "stage": stage,
        "accuracy_pct": 100 * accuracy_score(y_true, pred),
        "precision_pct": 100 * precision_score(y_true, pred, zero_division=0),
        "recall_pct": 100 * recall_score(y_true, pred, zero_division=0),
        "f1_pct": 100 * f1_score(y_true, pred, zero_division=0),
        "fpr_pct": 100 * fp / max(fp + tn, 1),
        "roc_auc": roc_auc_score(y_true, p),
        "log_loss": log_loss(y_true, np.column_stack([1 - p, p]), labels=[0, 1]),
        "latency_ms_per_sample": latency_ms
    }
    if extra:
        row.update(extra)
    print(pd.Series(row).to_string())
    return row


def casle_fit_transform(X_train, X_test, y_train, raw_train, raw_test, feature_names):
    banner("METHOD 1: CASLE | CAUSAL-ADAPTIVE SIGNATURE LEARNING ENGINE")
    start = time.perf_counter()
    mi_n = min(15000, len(X_train))
    rng = np.random.default_rng(SEED)
    mi_idx = rng.choice(len(X_train), mi_n, replace=False)
    mi = mutual_info_classif(X_train[mi_idx], y_train[mi_idx], random_state=SEED)
    mi_norm = minmax_1d(mi)
    adaptive_weights = 1.0 + 2.0 * mi_norm
    X_train_c = X_train * adaptive_weights
    X_test_c = X_test * adaptive_weights

    top_idx = np.argsort(mi)[::-1][:CASLE_GRAPH_FEATURES]
    seq = X_train_c[:min(12000, len(X_train_c)), top_idx]
    causal_matrix = np.zeros((len(top_idx), len(top_idx)), dtype=np.float64)
    for i in range(len(top_idx)):
        xi = seq[:-1, i]
        for j in range(len(top_idx)):
            if i == j:
                continue
            yj = seq[1:, j]
            if np.std(xi) > 1e-10 and np.std(yj) > 1e-10:
                causal_matrix[i, j] = abs(np.corrcoef(xi, yj)[0, 1]) * math.sqrt(mi_norm[top_idx[i]] * mi_norm[top_idx[j]] + 1e-12)

    edge_rows = []
    for i in range(len(top_idx)):
        for j in range(len(top_idx)):
            if i != j:
                edge_rows.append({
                    "source": feature_names[top_idx[i]],
                    "target": feature_names[top_idx[j]],
                    "lagged_causal_strength": causal_matrix[i, j]
                })
    edge_df = pd.DataFrame(edge_rows).sort_values("lagged_causal_strength", ascending=False).head(100)
    edge_df.to_csv(OUTPUT_DIR / "casle_causal_signature_graph_edges.csv", index=False)

    signature_weights = mi_norm / (mi_norm.sum() + 1e-12)
    train_projection = X_train_c @ signature_weights
    test_projection = X_test_c @ signature_weights
    signature_scaler = MinMaxScaler()
    train_signature = signature_scaler.fit_transform(train_projection.reshape(-1, 1)).ravel()
    test_signature = signature_scaler.transform(test_projection.reshape(-1, 1)).ravel()
    train_signature = np.clip(train_signature, 0, 1)
    test_signature = np.clip(test_signature, 0, 1)

    def rule_scores(df):
        serror = np.clip(safe_numeric(df, "serror_rate"), 0, 1)
        same_srv = np.clip(safe_numeric(df, "same_srv_rate"), 0, 1)
        count = np.clip(safe_numeric(df, "count") / 511.0, 0, 1)
        logged = np.clip(safe_numeric(df, "logged_in"), 0, 1)
        wrong = np.clip(safe_numeric(df, "wrong_fragment") / 3.0, 0, 1)
        failed = np.clip(safe_numeric(df, "num_failed_logins") / 5.0, 0, 1)
        dst_serror = np.clip(safe_numeric(df, "dst_host_serror_rate"), 0, 1)
        raw_score = 0.24 * serror + 0.18 * (1 - same_srv) + 0.15 * count + 0.13 * (1 - logged) + 0.10 * wrong + 0.08 * failed + 0.12 * dst_serror
        return np.clip(raw_score, 0, 1)

    train_rule = rule_scores(raw_train)
    test_rule = rule_scores(raw_test)
    test_casle_prob = np.clip(0.58 * test_signature + 0.42 * test_rule, 0, 1)
    latency = 1000 * (time.perf_counter() - start) / max(len(X_train) + len(X_test), 1)

    feature_table = pd.DataFrame({
        "feature": feature_names,
        "mutual_information": mi,
        "adaptive_weight": adaptive_weights
    }).sort_values("mutual_information", ascending=False)
    feature_table.to_csv(OUTPUT_DIR / "casle_adaptive_feature_weights.csv", index=False)
    pd.DataFrame({
        "signature_score": test_signature,
        "rule_score": test_rule,
        "casle_probability": test_casle_prob
    }).to_csv(OUTPUT_DIR / "casle_test_scores.csv", index=False)

    print(f"Encoded input dimensions: {X_train.shape[1]}")
    print(f"Causal graph nodes: {len(top_idx)}")
    print(f"Saved directed edges: {len(edge_df)}")
    print("Strongest causal-signature links:")
    print(edge_df.head(10).to_string(index=False))

    plt.figure(figsize=(7, 5))
    counts = np.bincount(y_train, minlength=2)
    plt.bar(["Normal", "Intrusion"], counts)
    plt.title("CASLE Input Class Distribution")
    plt.ylabel("Samples")
    save_plot("CASLE_1_input_class_distribution")

    plt.figure(figsize=(9, 6))
    top_show = feature_table.head(15).sort_values("mutual_information")
    plt.barh(top_show["feature"], top_show["mutual_information"])
    plt.title("CASLE Adaptive Signature Relevance")
    plt.xlabel("Mutual Information")
    save_plot("CASLE_2_signature_relevance")

    plt.figure(figsize=(8, 7))
    plt.imshow(causal_matrix, aspect="auto")
    plt.colorbar(label="Lagged Causal Strength")
    plt.xticks(range(len(top_idx)), [feature_names[i] for i in top_idx], rotation=90, fontsize=7)
    plt.yticks(range(len(top_idx)), [feature_names[i] for i in top_idx], fontsize=7)
    plt.title("CASLE Causal Signature Graph Matrix")
    save_plot("CASLE_3_causal_graph_matrix")

    plt.figure(figsize=(8, 5))
    plt.hist(test_signature[np.asarray(test_rule) < 0.5], bins=30, alpha=0.55, label="Lower rule activation")
    plt.hist(test_signature[np.asarray(test_rule) >= 0.5], bins=30, alpha=0.55, label="Higher rule activation")
    plt.title("CASLE Signature Score Distribution")
    plt.xlabel("Signature Score")
    plt.ylabel("Frequency")
    plt.legend()
    save_plot("CASLE_4_signature_score_distribution")

    sample_n = min(2500, len(test_signature))
    plt.figure(figsize=(7, 5))
    plt.scatter(test_rule[:sample_n], test_signature[:sample_n], c=test_casle_prob[:sample_n], s=12, alpha=0.6)
    plt.colorbar(label="CASLE Detection Probability")
    plt.xlabel("Rule Score")
    plt.ylabel("Causal Signature Score")
    plt.title("CASLE Rule-Signature Interaction")
    save_plot("CASLE_5_rule_signature_interaction")

    return {
        "X_train": X_train_c.astype(np.float32),
        "X_test": X_test_c.astype(np.float32),
        "train_signature": train_signature.astype(np.float32),
        "test_signature": test_signature.astype(np.float32),
        "train_rule": train_rule.astype(np.float32),
        "test_rule": test_rule.astype(np.float32),
        "test_prob": test_casle_prob.astype(np.float32),
        "latency": latency,
        "mi": mi,
        "feature_names": feature_names
    }


def build_autoencoder(input_dim):
    inputs = tf.keras.Input(shape=(input_dim,), name="egfc_input")
    x = tf.keras.layers.Dense(64, activation="relu")(inputs)
    x = tf.keras.layers.BatchNormalization()(x)
    x = tf.keras.layers.Dense(36, activation="relu")(x)
    latent = tf.keras.layers.Dense(LATENT_DIM, activation="tanh", name="entropy_feature_tensor")(x)
    x = tf.keras.layers.Dense(36, activation="relu")(latent)
    x = tf.keras.layers.Dense(64, activation="relu")(x)
    outputs = tf.keras.layers.Dense(input_dim, name="reconstruction")(x)
    autoencoder = tf.keras.Model(inputs, outputs, name="EGFC_Autoencoder")
    encoder = tf.keras.Model(inputs, latent, name="EGFC_Encoder")
    autoencoder.compile(optimizer=tf.keras.optimizers.Adam(1e-3), loss="mse", metrics=["mae"])
    return autoencoder, encoder


def egfc_fit_transform(casle, y_train, y_test):
    banner("METHOD 2: EGFC-NET | ENTROPY-GUIDED FEATURE COMPRESSION NETWORK")
    start = time.perf_counter()
    X_train = casle["X_train"]
    X_test = casle["X_test"]
    feature_names = np.array(casle["feature_names"])

    entropy = np.array([calculate_entropy_column(X_train[:, j]) for j in range(X_train.shape[1])])
    entropy_norm = minmax_1d(entropy)
    relevance = minmax_1d(casle["mi"])

    corr_sample = X_train[:min(12000, len(X_train))]
    corr = np.corrcoef(corr_sample, rowvar=False)
    corr = np.nan_to_num(np.abs(corr), nan=0.0)
    redundancy = (corr.sum(axis=1) - 1.0) / max(corr.shape[1] - 1, 1)
    redundancy_norm = minmax_1d(redundancy)
    egfc_score = 0.55 * relevance + 0.30 * entropy_norm + 0.15 * (1 - redundancy_norm)
    selected_idx = np.argsort(egfc_score)[::-1][:min(EGFC_SELECTED_FEATURES, X_train.shape[1])]

    ranking = pd.DataFrame({
        "feature": feature_names,
        "entropy": entropy,
        "relevance": relevance,
        "redundancy": redundancy,
        "egfc_score": egfc_score,
        "selected": np.isin(np.arange(len(feature_names)), selected_idx).astype(int)
    }).sort_values("egfc_score", ascending=False)
    ranking.to_csv(OUTPUT_DIR / "egfc_feature_ranking.csv", index=False)

    Xs_train = X_train[:, selected_idx].astype(np.float32)
    Xs_test = X_test[:, selected_idx].astype(np.float32)
    autoencoder, encoder = build_autoencoder(Xs_train.shape[1])
    callbacks = [tf.keras.callbacks.EarlyStopping(monitor="val_loss", patience=2, restore_best_weights=True)]
    history = autoencoder.fit(
        Xs_train, Xs_train,
        validation_split=0.15,
        epochs=AUTOENCODER_EPOCHS,
        batch_size=BATCH_SIZE,
        verbose=2,
        callbacks=callbacks
    )

    Z_train = encoder.predict(Xs_train, batch_size=1024, verbose=0)
    Z_test = encoder.predict(Xs_test, batch_size=1024, verbose=0)
    rec_test = autoencoder.predict(Xs_test, batch_size=1024, verbose=0)
    rec_error = np.mean(np.square(Xs_test - rec_test), axis=1)
    latency = 1000 * (time.perf_counter() - start) / max(len(X_train) + len(X_test), 1)

    latent_cols = [f"EGFC_Z{i+1}" for i in range(Z_test.shape[1])]
    latent_out = pd.DataFrame(Z_test[:min(10000, len(Z_test))], columns=latent_cols)
    latent_out["label"] = y_test[:len(latent_out)]
    latent_out["reconstruction_error"] = rec_error[:len(latent_out)]
    latent_out.to_csv(OUTPUT_DIR / "egfc_entropy_feature_tensor_test.csv", index=False)
    autoencoder.save(OUTPUT_DIR / "egfc_autoencoder.keras")
    encoder.save(OUTPUT_DIR / "egfc_encoder.keras")

    print(f"CASLE input dimensions: {X_train.shape[1]}")
    print(f"EGFC selected dimensions: {Xs_train.shape[1]}")
    print(f"Entropy feature tensor dimensions: {Z_train.shape[1]}")
    print(f"Feature reduction: {100 * (1 - Z_train.shape[1] / X_train.shape[1]):.2f}%")
    print("Top entropy-optimized features:")
    print(ranking.head(15).to_string(index=False))

    plt.figure(figsize=(9, 6))
    show = ranking.head(18).sort_values("entropy")
    plt.barh(show["feature"], show["entropy"])
    plt.title("EGFC-Net Feature Entropy")
    plt.xlabel("Entropy")
    save_plot("EGFC_1_feature_entropy")

    plt.figure(figsize=(9, 6))
    show = ranking.head(18).sort_values("egfc_score")
    plt.barh(show["feature"], show["egfc_score"])
    plt.title("EGFC-Net Entropy-Relevance Ranking")
    plt.xlabel("EGFC Score")
    save_plot("EGFC_2_feature_ranking")

    plt.figure(figsize=(7, 5))
    plt.plot(history.history["loss"], marker="o", label="Training")
    plt.plot(history.history["val_loss"], marker="o", label="Validation")
    plt.title("EGFC-Net Reconstruction Loss")
    plt.xlabel("Epoch")
    plt.ylabel("MSE")
    plt.legend()
    save_plot("EGFC_3_autoencoder_loss")

    plt.figure(figsize=(7, 5))
    plt.hist(rec_error[y_test == 0], bins=35, alpha=0.6, label="Normal")
    plt.hist(rec_error[y_test == 1], bins=35, alpha=0.6, label="Intrusion")
    plt.title("EGFC-Net Reconstruction Error")
    plt.xlabel("Reconstruction Error")
    plt.ylabel("Frequency")
    plt.legend()
    save_plot("EGFC_4_reconstruction_error")

    pca = PCA(n_components=2, random_state=SEED)
    nvis = min(5000, len(Z_test))
    z2 = pca.fit_transform(Z_test[:nvis])
    plt.figure(figsize=(7, 5))
    plt.scatter(z2[:, 0], z2[:, 1], c=y_test[:nvis], s=10, alpha=0.55)
    plt.colorbar(label="Class: 0 Normal, 1 Intrusion")
    plt.title("EGFC Entropy Feature Tensor Projection")
    plt.xlabel("Principal Component 1")
    plt.ylabel("Principal Component 2")
    save_plot("EGFC_5_latent_projection")

    return {
        "Z_train": Z_train.astype(np.float32),
        "Z_test": Z_test.astype(np.float32),
        "rec_error_train": np.mean(np.square(Xs_train - autoencoder.predict(Xs_train, batch_size=1024, verbose=0)), axis=1).astype(np.float32),
        "rec_error_test": rec_error.astype(np.float32),
        "selected_features": feature_names[selected_idx].tolist(),
        "selected_count": len(selected_idx),
        "original_count": X_train.shape[1],
        "autoencoder_history": history.history,
        "latency": latency
    }


def build_deep_stream(latent_dim):
    inputs = tf.keras.Input(shape=(latent_dim,), name="entropy_tensor_input")
    x = tf.keras.layers.Reshape((latent_dim, 1))(inputs)
    x = tf.keras.layers.Conv1D(32, 3, padding="same", activation="relu")(x)
    x = tf.keras.layers.MaxPooling1D(2)(x)
    x = tf.keras.layers.Bidirectional(tf.keras.layers.GRU(24))(x)
    x = tf.keras.layers.Dense(32, activation="relu")(x)
    x = tf.keras.layers.Dropout(0.20)(x)
    output = tf.keras.layers.Dense(1, activation="sigmoid", name="deep_probability")(x)
    model = tf.keras.Model(inputs, output, name="HCDS_Deep_Stream")
    model.compile(optimizer=tf.keras.optimizers.Adam(8e-4), loss="binary_crossentropy", metrics=["accuracy", tf.keras.metrics.AUC(name="auc")])
    return model


def build_fusion_model():
    streams = tf.keras.Input(shape=(3,), name="detection_streams")
    a = tf.keras.layers.Dense(8, activation="relu")(streams)
    attention = tf.keras.layers.Dense(3, activation="softmax", name="context_attention")(a)
    weighted = tf.keras.layers.Multiply()([streams, attention])
    x = tf.keras.layers.Concatenate()([streams, weighted])
    x = tf.keras.layers.Dense(10, activation="relu")(x)
    output = tf.keras.layers.Dense(1, activation="sigmoid", name="cognitive_probability")(x)
    model = tf.keras.Model(streams, output, name="HCDS_Cognitive_Fusion")
    attention_model = tf.keras.Model(streams, attention, name="HCDS_Attention_Extractor")
    model.compile(optimizer=tf.keras.optimizers.Adam(1e-3), loss="binary_crossentropy", metrics=["accuracy", tf.keras.metrics.AUC(name="auc")])
    return model, attention_model


def scale_anomaly_scores(train_scores, test_scores):
    scaler = MinMaxScaler()
    train_p = scaler.fit_transform(train_scores.reshape(-1, 1)).ravel()
    test_p = scaler.transform(test_scores.reshape(-1, 1)).ravel()
    return np.clip(train_p, 0, 1), np.clip(test_p, 0, 1), scaler


def hcds_fit(casle, egfc, y_train, y_test):
    banner("METHOD 3: HCDS | HYBRID COGNITIVE DETECTION SYNTHESIZER")
    start = time.perf_counter()
    Z_train, Z_test = egfc["Z_train"], egfc["Z_test"]
    deep_model = build_deep_stream(Z_train.shape[1])
    callbacks = [tf.keras.callbacks.EarlyStopping(monitor="val_auc", mode="max", patience=2, restore_best_weights=True)]
    deep_history = deep_model.fit(
        Z_train, y_train,
        validation_split=0.15,
        epochs=HCDS_EPOCHS,
        batch_size=BATCH_SIZE,
        verbose=2,
        callbacks=callbacks
    )
    deep_train = deep_model.predict(Z_train, batch_size=1024, verbose=0).ravel()
    deep_test = deep_model.predict(Z_test, batch_size=1024, verbose=0).ravel()

    iso_fit_n = min(25000, len(Z_train))
    iso = IsolationForest(n_estimators=120, contamination="auto", random_state=SEED, n_jobs=-1)
    iso.fit(Z_train[:iso_fit_n])
    anomaly_train_raw = -iso.decision_function(Z_train)
    anomaly_test_raw = -iso.decision_function(Z_test)
    anomaly_train, anomaly_test, anomaly_scaler = scale_anomaly_scores(anomaly_train_raw, anomaly_test_raw)

    rule_train = np.clip(0.55 * casle["train_rule"] + 0.45 * casle["train_signature"], 0, 1)
    rule_test = np.clip(0.55 * casle["test_rule"] + 0.45 * casle["test_signature"], 0, 1)
    streams_train = np.column_stack([deep_train, rule_train, anomaly_train]).astype(np.float32)
    streams_test = np.column_stack([deep_test, rule_test, anomaly_test]).astype(np.float32)

    fusion_model, attention_model = build_fusion_model()
    fusion_history = fusion_model.fit(
        streams_train, y_train,
        validation_split=0.15,
        epochs=FUSION_EPOCHS,
        batch_size=BATCH_SIZE,
        verbose=2,
        callbacks=[tf.keras.callbacks.EarlyStopping(monitor="val_auc", mode="max", patience=2, restore_best_weights=True)]
    )
    fused_train = fusion_model.predict(streams_train, batch_size=1024, verbose=0).ravel()
    fused_test = fusion_model.predict(streams_test, batch_size=1024, verbose=0).ravel()
    att_train = attention_model.predict(streams_train, batch_size=1024, verbose=0)
    att_test = attention_model.predict(streams_test, batch_size=1024, verbose=0)
    latency = 1000 * (time.perf_counter() - start) / max(len(Z_train) + len(Z_test), 1)

    cognitive = pd.DataFrame({
        "deep_probability": deep_test,
        "rule_signature_probability": rule_test,
        "anomaly_probability": anomaly_test,
        "attention_deep": att_test[:, 0],
        "attention_rule": att_test[:, 1],
        "attention_anomaly": att_test[:, 2],
        "hcds_probability": fused_test,
        "label": y_test
    })
    cognitive.to_csv(OUTPUT_DIR / "hcds_cognitive_detection_matrix.csv", index=False)
    deep_model.save(OUTPUT_DIR / "hcds_deep_stream.keras")
    fusion_model.save(OUTPUT_DIR / "hcds_fusion_model.keras")

    print("Mean contextual attention weights:")
    print(pd.Series(att_test.mean(axis=0), index=["Deep stream", "Rule-signature stream", "Anomaly stream"]).to_string())
    print("Cognitive detection matrix sample:")
    print(cognitive.head(10).to_string(index=False))

    plt.figure(figsize=(7, 5))
    plt.plot(deep_history.history["accuracy"], marker="o", label="Training")
    plt.plot(deep_history.history["val_accuracy"], marker="o", label="Validation")
    plt.title("HCDS Deep Stream Accuracy")
    plt.xlabel("Epoch")
    plt.ylabel("Accuracy")
    plt.legend()
    save_plot("HCDS_1_deep_accuracy")

    plt.figure(figsize=(7, 5))
    plt.plot(deep_history.history["loss"], marker="o", label="Training")
    plt.plot(deep_history.history["val_loss"], marker="o", label="Validation")
    plt.title("HCDS Deep Stream Loss")
    plt.xlabel("Epoch")
    plt.ylabel("Binary Cross-Entropy")
    plt.legend()
    save_plot("HCDS_2_deep_loss")

    plt.figure(figsize=(8, 5))
    plt.hist(deep_test, bins=35, alpha=0.45, label="Deep")
    plt.hist(rule_test, bins=35, alpha=0.45, label="Rule-Signature")
    plt.hist(anomaly_test, bins=35, alpha=0.45, label="Anomaly")
    plt.title("HCDS Input Detection Streams")
    plt.xlabel("Probability")
    plt.ylabel("Frequency")
    plt.legend()
    save_plot("HCDS_3_detection_streams")

    plt.figure(figsize=(7, 5))
    for p, label in [(deep_test, "Deep"), (rule_test, "Rule-Signature"), (anomaly_test, "Anomaly"), (fused_test, "Cognitive Fusion")]:
        fpr, tpr, _ = roc_curve(y_test, p)
        plt.plot(fpr, tpr, label=f"{label} AUC={roc_auc_score(y_test, p):.3f}")
    plt.plot([0, 1], [0, 1], linestyle="--")
    plt.title("HCDS ROC Analysis")
    plt.xlabel("False Positive Rate")
    plt.ylabel("True Positive Rate")
    plt.legend()
    save_plot("HCDS_4_roc_analysis")

    cm = confusion_matrix(y_test, fused_test >= 0.5)
    plt.figure(figsize=(6, 5))
    plt.imshow(cm)
    plt.colorbar()
    for i in range(2):
        for j in range(2):
            plt.text(j, i, cm[i, j], ha="center", va="center")
    plt.xticks([0, 1], ["Normal", "Intrusion"])
    plt.yticks([0, 1], ["Normal", "Intrusion"])
    plt.xlabel("Predicted")
    plt.ylabel("Actual")
    plt.title("HCDS Cognitive Detection Matrix")
    save_plot("HCDS_5_confusion_matrix")

    return {
        "deep_model": deep_model,
        "fusion_model": fusion_model,
        "attention_model": attention_model,
        "isolation_forest": iso,
        "anomaly_scaler": anomaly_scaler,
        "deep_train": deep_train.astype(np.float32),
        "deep_test": deep_test.astype(np.float32),
        "anomaly_train": anomaly_train.astype(np.float32),
        "anomaly_test": anomaly_test.astype(np.float32),
        "rule_train": rule_train.astype(np.float32),
        "rule_test": rule_test.astype(np.float32),
        "streams_train": streams_train,
        "streams_test": streams_test,
        "fused_train": fused_train.astype(np.float32),
        "fused_test": fused_test.astype(np.float32),
        "attention_train": att_train.astype(np.float32),
        "attention_test": att_test.astype(np.float32),
        "deep_history": deep_history.history,
        "fusion_history": fusion_history.history,
        "latency": latency
    }


def fgsm_attack(model, X, y, epsilon, batch_size=512):
    adversarial = []
    for start in range(0, len(X), batch_size):
        xb = tf.convert_to_tensor(X[start:start + batch_size], dtype=tf.float32)
        yb = tf.convert_to_tensor(y[start:start + batch_size].reshape(-1, 1), dtype=tf.float32)
        with tf.GradientTape() as tape:
            tape.watch(xb)
            pred = model(xb, training=False)
            loss = tf.keras.losses.binary_crossentropy(yb, pred)
        grad = tape.gradient(loss, xb)
        x_adv = xb + epsilon * tf.sign(grad)
        adversarial.append(x_adv.numpy())
    return np.vstack(adversarial).astype(np.float32)


def temperature_scale(probabilities, temperature):
    p = np.clip(probabilities, 1e-6, 1 - 1e-6)
    logits = np.log(p / (1 - p)) / max(float(temperature), 1e-4)
    return sigmoid_np(logits)


def find_temperature(y, probabilities):
    candidates = np.linspace(0.50, 3.00, 51)
    losses = []
    for t in candidates:
        p = temperature_scale(probabilities, t)
        losses.append(log_loss(y, np.column_stack([1 - p, p]), labels=[0, 1]))
    return float(candidates[int(np.argmin(losses))])


def arcm_calibrate(hcds, egfc, casle, y_train, y_test):
    banner("METHOD 4: ARCM | ADVERSARIAL ROBUSTNESS CALIBRATION MODULE")
    start = time.perf_counter()
    Z_train, Z_test = egfc["Z_train"], egfc["Z_test"]
    deep_model = hcds["deep_model"]
    fusion_model = hcds["fusion_model"]

    Z_adv_train = fgsm_attack(deep_model, Z_train, y_train, FGSM_EPSILON)
    Z_adv_test = fgsm_attack(deep_model, Z_test, y_test, FGSM_EPSILON)
    deep_adv_train = deep_model.predict(Z_adv_train, batch_size=1024, verbose=0).ravel()
    deep_adv_test = deep_model.predict(Z_adv_test, batch_size=1024, verbose=0).ravel()

    anomaly_adv_train_raw = -hcds["isolation_forest"].decision_function(Z_adv_train)
    anomaly_adv_test_raw = -hcds["isolation_forest"].decision_function(Z_adv_test)
    anomaly_adv_train = np.clip(hcds["anomaly_scaler"].transform(anomaly_adv_train_raw.reshape(-1, 1)).ravel(), 0, 1)
    anomaly_adv_test = np.clip(hcds["anomaly_scaler"].transform(anomaly_adv_test_raw.reshape(-1, 1)).ravel(), 0, 1)

    adv_streams_train = np.column_stack([deep_adv_train, hcds["rule_train"], anomaly_adv_train]).astype(np.float32)
    adv_streams_test = np.column_stack([deep_adv_test, hcds["rule_test"], anomaly_adv_test]).astype(np.float32)
    fused_adv_train = fusion_model.predict(adv_streams_train, batch_size=1024, verbose=0).ravel()
    fused_adv_test = fusion_model.predict(adv_streams_test, batch_size=1024, verbose=0).ravel()

    temperature = find_temperature(y_train, np.concatenate([hcds["fused_train"], fused_adv_train])) if False else find_temperature(y_train, hcds["fused_train"])
    clean_cal_train = temperature_scale(hcds["fused_train"], temperature)
    clean_cal_test = temperature_scale(hcds["fused_test"], temperature)
    adv_cal_train = temperature_scale(fused_adv_train, temperature)
    adv_cal_test = temperature_scale(fused_adv_test, temperature)

    stability_train = np.clip(1.0 - np.abs(clean_cal_train - adv_cal_train), 0, 1)
    stability_test = np.clip(1.0 - np.abs(clean_cal_test - adv_cal_test), 0, 1)
    robust_train = np.clip(0.5 * (clean_cal_train + adv_cal_train), 0, 1)
    robust_test = np.clip(0.5 * (clean_cal_test + adv_cal_test), 0, 1)
    latency = 1000 * (time.perf_counter() - start) / max(len(Z_train) + len(Z_test), 1)

    arcm_df = pd.DataFrame({
        "clean_hcds_probability": clean_cal_test,
        "adversarial_hcds_probability": adv_cal_test,
        "robust_detection_score": robust_test,
        "stability_index": stability_test,
        "fgsm_epsilon": FGSM_EPSILON,
        "label": y_test
    })
    arcm_df.to_csv(OUTPUT_DIR / "arcm_robust_detection_scores.csv", index=False)

    clean_acc = accuracy_score(y_test, clean_cal_test >= 0.5)
    adv_acc = accuracy_score(y_test, adv_cal_test >= 0.5)
    robust_acc = accuracy_score(y_test, robust_test >= 0.5)
    print(f"Optimal temperature: {temperature:.3f}")
    print(f"Clean HCDS accuracy: {100 * clean_acc:.3f}%")
    print(f"Adversarial HCDS accuracy: {100 * adv_acc:.3f}%")
    print(f"Robust-score accuracy: {100 * robust_acc:.3f}%")
    print(f"Mean stability index: {stability_test.mean():.4f}")

    plt.figure(figsize=(7, 5))
    plt.bar(["Clean", "Adversarial", "Robust calibrated"], [100 * clean_acc, 100 * adv_acc, 100 * robust_acc])
    plt.ylabel("Accuracy (%)")
    plt.title("ARCM Clean and Adversarial Performance")
    save_plot("ARCM_1_clean_adversarial_accuracy")

    eps_grid = [0.0, 0.005, 0.010, 0.020, 0.035, 0.050]
    eps_acc = []
    subset_n = min(3000, len(Z_test))
    for eps in eps_grid:
        if eps == 0:
            p = hcds["fused_test"][:subset_n]
        else:
            z_adv = fgsm_attack(deep_model, Z_test[:subset_n], y_test[:subset_n], eps)
            d_adv = deep_model.predict(z_adv, batch_size=1024, verbose=0).ravel()
            a_raw = -hcds["isolation_forest"].decision_function(z_adv)
            a = np.clip(hcds["anomaly_scaler"].transform(a_raw.reshape(-1, 1)).ravel(), 0, 1)
            s = np.column_stack([d_adv, hcds["rule_test"][:subset_n], a]).astype(np.float32)
            p = fusion_model.predict(s, batch_size=1024, verbose=0).ravel()
        eps_acc.append(100 * accuracy_score(y_test[:subset_n], p >= 0.5))
    pd.DataFrame({"epsilon": eps_grid, "accuracy_pct": eps_acc}).to_csv(OUTPUT_DIR / "arcm_epsilon_robustness.csv", index=False)
    plt.figure(figsize=(7, 5))
    plt.plot(eps_grid, eps_acc, marker="o")
    plt.xlabel("FGSM Epsilon")
    plt.ylabel("Accuracy (%)")
    plt.title("ARCM Robustness Sensitivity")
    save_plot("ARCM_2_epsilon_sensitivity")

    plt.figure(figsize=(7, 5))
    nscatter = min(3000, len(clean_cal_test))
    plt.scatter(clean_cal_test[:nscatter], adv_cal_test[:nscatter], c=stability_test[:nscatter], s=12, alpha=0.6)
    plt.plot([0, 1], [0, 1], linestyle="--")
    plt.colorbar(label="Stability Index")
    plt.xlabel("Clean Probability")
    plt.ylabel("Adversarial Probability")
    plt.title("ARCM Probability Stability")
    save_plot("ARCM_3_probability_stability")

    prob_true, prob_pred = calibration_curve(y_test, robust_test, n_bins=10, strategy="quantile")
    plt.figure(figsize=(7, 5))
    plt.plot(prob_pred, prob_true, marker="o", label="ARCM")
    plt.plot([0, 1], [0, 1], linestyle="--", label="Perfect calibration")
    plt.xlabel("Mean Predicted Probability")
    plt.ylabel("Observed Intrusion Frequency")
    plt.title("ARCM Calibration Curve")
    plt.legend()
    save_plot("ARCM_4_calibration_curve")

    plt.figure(figsize=(7, 5))
    plt.hist(stability_test[y_test == 0], bins=35, alpha=0.6, label="Normal")
    plt.hist(stability_test[y_test == 1], bins=35, alpha=0.6, label="Intrusion")
    plt.xlabel("Stability Index")
    plt.ylabel("Frequency")
    plt.title("ARCM Detection Stability Distribution")
    plt.legend()
    save_plot("ARCM_5_stability_distribution")

    return {
        "Z_adv_train": Z_adv_train,
        "Z_adv_test": Z_adv_test,
        "clean_train": clean_cal_train.astype(np.float32),
        "clean_test": clean_cal_test.astype(np.float32),
        "adv_train": adv_cal_train.astype(np.float32),
        "adv_test": adv_cal_test.astype(np.float32),
        "robust_train": robust_train.astype(np.float32),
        "robust_test": robust_test.astype(np.float32),
        "stability_train": stability_train.astype(np.float32),
        "stability_test": stability_test.astype(np.float32),
        "temperature": temperature,
        "latency": latency
    }


def build_federated_model(input_dim):
    inputs = tf.keras.Input(shape=(input_dim,), name="federated_threat_vector")
    x = tf.keras.layers.Dense(40, activation="relu")(inputs)
    x = tf.keras.layers.BatchNormalization()(x)
    x = tf.keras.layers.Dense(20, activation="relu")(x)
    x = tf.keras.layers.Dropout(0.15)(x)
    output = tf.keras.layers.Dense(1, activation="sigmoid", name="global_intrusion_probability")(x)
    model = tf.keras.Model(inputs, output, name="FTIEF_Global_Model")
    model.compile(optimizer=tf.keras.optimizers.Adam(6e-4), loss="binary_crossentropy", metrics=["accuracy", tf.keras.metrics.AUC(name="auc")])
    return model


def make_client_indices(y, n_clients, alpha=0.8):
    rng = np.random.default_rng(SEED)
    clients = [[] for _ in range(n_clients)]
    for cls in np.unique(y):
        idx = np.where(y == cls)[0]
        rng.shuffle(idx)
        proportions = rng.dirichlet(np.repeat(alpha, n_clients))
        cuts = (np.cumsum(proportions)[:-1] * len(idx)).astype(int)
        splits = np.split(idx, cuts)
        for k, part in enumerate(splits):
            clients[k].extend(part.tolist())
    clients = [np.array(c, dtype=int) for c in clients]
    if min(map(len, clients)) < 200:
        skf = StratifiedKFold(n_splits=n_clients, shuffle=True, random_state=SEED)
        clients = [test_idx for _, test_idx in skf.split(np.zeros(len(y)), y)]
    return clients


def aggregate_weights(local_weights, aggregation_weights):
    total = np.sum(aggregation_weights)
    agg = []
    for layer_parts in zip(*local_weights):
        layer = np.zeros_like(layer_parts[0])
        for w, coeff in zip(layer_parts, aggregation_weights):
            layer += w * (coeff / total)
        agg.append(layer)
    return agg


def ftief_train(egfc, hcds, arcm, y_train, y_test):
    banner("METHOD 5: FTIEF | FEDERATED THREAT INTELLIGENCE EVOLUTION FRAMEWORK")
    start = time.perf_counter()
    X_train = np.column_stack([
        egfc["Z_train"],
        hcds["fused_train"],
        arcm["robust_train"],
        arcm["stability_train"]
    ]).astype(np.float32)
    X_test = np.column_stack([
        egfc["Z_test"],
        hcds["fused_test"],
        arcm["robust_test"],
        arcm["stability_test"]
    ]).astype(np.float32)

    X_fed, X_val, y_fed, y_val = train_test_split(
        X_train, y_train, test_size=0.15, stratify=y_train, random_state=SEED
    )
    client_indices = make_client_indices(y_fed, FED_CLIENTS, alpha=0.75)
    global_model = build_federated_model(X_train.shape[1])
    global_weights = global_model.get_weights()
    model_bytes = int(sum(w.nbytes for w in global_weights))
    round_rows = []
    trust_history = []
    cumulative_communication = 0

    print("Federated client distributions:")
    client_rows = []
    for cid, idx in enumerate(client_indices):
        row = {
            "client": cid + 1,
            "samples": len(idx),
            "normal": int((y_fed[idx] == 0).sum()),
            "intrusion": int((y_fed[idx] == 1).sum()),
            "intrusion_ratio": float(y_fed[idx].mean())
        }
        client_rows.append(row)
        print(row)
    pd.DataFrame(client_rows).to_csv(OUTPUT_DIR / "ftief_client_distributions.csv", index=False)

    for round_id in range(1, FED_ROUNDS + 1):
        local_weights = []
        local_acc = []
        local_loss = []
        local_sizes = []
        for cid, idx in enumerate(client_indices):
            local_model = build_federated_model(X_train.shape[1])
            local_model.set_weights(global_weights)
            hist = local_model.fit(
                X_fed[idx], y_fed[idx],
                epochs=LOCAL_EPOCHS,
                batch_size=BATCH_SIZE,
                verbose=0
            )
            val_eval = local_model.evaluate(X_val, y_val, batch_size=1024, verbose=0)
            local_weights.append(local_model.get_weights())
            local_loss.append(float(val_eval[0]))
            local_acc.append(float(val_eval[1]))
            local_sizes.append(len(idx))
            print(f"Round {round_id} | Client {cid+1} | samples={len(idx)} | val_acc={val_eval[1]:.4f} | val_auc={val_eval[2]:.4f}")
            tf.keras.backend.clear_session()

        acc_array = np.array(local_acc)
        trust = sigmoid_np(12.0 * (acc_array - np.mean(acc_array)))
        aggregation_weights = np.array(local_sizes, dtype=float) * (0.25 + 0.75 * trust)
        global_weights = aggregate_weights(local_weights, aggregation_weights)
        global_model = build_federated_model(X_train.shape[1])
        global_model.set_weights(global_weights)
        val_loss, val_acc, val_auc = global_model.evaluate(X_val, y_val, batch_size=1024, verbose=0)
        cumulative_communication += 2 * FED_CLIENTS * model_bytes
        round_rows.append({
            "round": round_id,
            "validation_loss": val_loss,
            "validation_accuracy": val_acc,
            "validation_auc": val_auc,
            "mean_client_accuracy": float(np.mean(local_acc)),
            "mean_trust": float(np.mean(trust)),
            "communication_mb": cumulative_communication / (1024 ** 2)
        })
        for cid, t in enumerate(trust):
            trust_history.append({"round": round_id, "client": cid + 1, "trust_weight": float(t), "local_accuracy": local_acc[cid]})
        print(f"Global round {round_id}: val_accuracy={val_acc:.4f}, val_auc={val_auc:.4f}, communication={cumulative_communication/(1024**2):.3f} MB")

    global_model.set_weights(global_weights)
    inference_start = time.perf_counter()
    final_prob = global_model.predict(X_test, batch_size=1024, verbose=0).ravel()
    inference_latency = 1000 * (time.perf_counter() - inference_start) / max(len(X_test), 1)
    total_latency = 1000 * (time.perf_counter() - start) / max(len(X_train) + len(X_test), 1)

    rounds_df = pd.DataFrame(round_rows)
    trust_df = pd.DataFrame(trust_history)
    rounds_df.to_csv(OUTPUT_DIR / "ftief_federated_round_metrics.csv", index=False)
    trust_df.to_csv(OUTPUT_DIR / "ftief_client_trust_weights.csv", index=False)
    pd.DataFrame({
        "global_probability": final_prob,
        "predicted_label": (final_prob >= 0.5).astype(int),
        "actual_label": y_test,
        "hcds_probability": hcds["fused_test"],
        "arcm_robust_score": arcm["robust_test"],
        "arcm_stability": arcm["stability_test"]
    }).to_csv(OUTPUT_DIR / "ftief_global_threat_intelligence_predictions.csv", index=False)
    global_model.save(OUTPUT_DIR / "ftief_global_threat_intelligence_model.keras")

    print("Final global threat-intelligence predictions:")
    print(pd.DataFrame({"actual": y_test[:15], "probability": final_prob[:15], "prediction": (final_prob[:15] >= 0.5).astype(int)}).to_string(index=False))

    client_df = pd.DataFrame(client_rows)
    plt.figure(figsize=(8, 5))
    x = np.arange(len(client_df))
    plt.bar(x, client_df["normal"], label="Normal")
    plt.bar(x, client_df["intrusion"], bottom=client_df["normal"], label="Intrusion")
    plt.xticks(x, [f"Client {i}" for i in client_df["client"]])
    plt.ylabel("Samples")
    plt.title("FTIEF Non-IID Client Traffic Distribution")
    plt.legend()
    save_plot("FTIEF_1_client_distribution")

    plt.figure(figsize=(7, 5))
    plt.plot(rounds_df["round"], 100 * rounds_df["validation_accuracy"], marker="o")
    plt.xlabel("Federated Round")
    plt.ylabel("Validation Accuracy (%)")
    plt.title("FTIEF Global Accuracy Evolution")
    save_plot("FTIEF_2_global_accuracy")

    plt.figure(figsize=(7, 5))
    plt.plot(rounds_df["round"], rounds_df["validation_loss"], marker="o")
    plt.xlabel("Federated Round")
    plt.ylabel("Validation Loss")
    plt.title("FTIEF Global Loss Evolution")
    save_plot("FTIEF_3_global_loss")

    last_trust = trust_df[trust_df["round"] == FED_ROUNDS]
    plt.figure(figsize=(7, 5))
    plt.bar([f"Client {i}" for i in last_trust["client"]], last_trust["trust_weight"])
    plt.ylim(0, 1)
    plt.ylabel("Trust Weight")
    plt.title("FTIEF Final-Round Trust Weights")
    save_plot("FTIEF_4_trust_weights")

    cm = confusion_matrix(y_test, final_prob >= 0.5)
    plt.figure(figsize=(6, 5))
    plt.imshow(cm)
    plt.colorbar()
    for i in range(2):
        for j in range(2):
            plt.text(j, i, cm[i, j], ha="center", va="center")
    plt.xticks([0, 1], ["Normal", "Intrusion"])
    plt.yticks([0, 1], ["Normal", "Intrusion"])
    plt.xlabel("Predicted")
    plt.ylabel("Actual")
    plt.title("FTIEF Global Threat Intelligence Matrix")
    save_plot("FTIEF_5_global_confusion_matrix")

    return {
        "model": global_model,
        "prob": final_prob.astype(np.float32),
        "rounds": rounds_df,
        "trust": trust_df,
        "communication_mb": cumulative_communication / (1024 ** 2),
        "inference_latency": inference_latency,
        "total_latency": total_latency,
        "input_dim": X_train.shape[1],
        "model_bytes": model_bytes
    }


def final_evaluation(y_train, y_test, casle, egfc, hcds, arcm, ftief, total_runtime):
    banner("INTEGRATED EFFICIENCY AND DETECTION ANALYSIS")
    metrics = []
    metrics.append(metric_row("CASLE Causal-Signature Detection", y_test, casle["test_prob"], casle["latency"]))

    latent_clf = LogisticRegression(max_iter=500, class_weight="balanced", random_state=SEED)
    latent_clf.fit(egfc["Z_train"], y_train)
    t0 = time.perf_counter()
    egfc_prob = latent_clf.predict_proba(egfc["Z_test"])[:, 1]
    egfc_latency = 1000 * (time.perf_counter() - t0) / len(y_test)
    metrics.append(metric_row(
        "EGFC-Net Entropy Tensor", y_test, egfc_prob, egfc_latency,
        extra={"feature_reduction_pct": 100 * (1 - egfc["Z_test"].shape[1] / egfc["original_count"])}
    ))

    metrics.append(metric_row("HCDS Cognitive Fusion", y_test, hcds["fused_test"], hcds["latency"]))
    metrics.append(metric_row(
        "ARCM Robust Detection", y_test, arcm["robust_test"], arcm["latency"],
        extra={"robustness_score": float(arcm["stability_test"].mean())}
    ))
    metrics.append(metric_row(
        "FTIEF Global Threat Intelligence", y_test, ftief["prob"], ftief["inference_latency"],
        extra={"communication_mb": ftief["communication_mb"]}
    ))

    adv_metrics = metric_row("ARCM Adversarial Evaluation", y_test, arcm["adv_test"], 0.0)
    metrics.append(adv_metrics)
    metrics_df = pd.DataFrame(metrics)
    metrics_df.to_csv(OUTPUT_DIR / "integrated_stage_metrics.csv", index=False)

    final_summary = {
        "dataset": "KDD Cup 1999 10% benchmark",
        "working_samples": int(len(y_train) + len(y_test)),
        "training_samples": int(len(y_train)),
        "test_samples": int(len(y_test)),
        "encoded_input_features": int(egfc["original_count"]),
        "egfc_selected_features": int(egfc["selected_count"]),
        "entropy_tensor_dimensions": int(egfc["Z_test"].shape[1]),
        "dimensionality_reduction_pct": float(100 * (1 - egfc["Z_test"].shape[1] / egfc["original_count"])),
        "arcm_fgsm_epsilon": FGSM_EPSILON,
        "arcm_mean_stability": float(arcm["stability_test"].mean()),
        "federated_clients": FED_CLIENTS,
        "federated_rounds": FED_ROUNDS,
        "federated_communication_mb": float(ftief["communication_mb"]),
        "final_accuracy_pct": float(metrics_df.loc[metrics_df.stage == "FTIEF Global Threat Intelligence", "accuracy_pct"].iloc[0]),
        "final_precision_pct": float(metrics_df.loc[metrics_df.stage == "FTIEF Global Threat Intelligence", "precision_pct"].iloc[0]),
        "final_recall_pct": float(metrics_df.loc[metrics_df.stage == "FTIEF Global Threat Intelligence", "recall_pct"].iloc[0]),
        "final_f1_pct": float(metrics_df.loc[metrics_df.stage == "FTIEF Global Threat Intelligence", "f1_pct"].iloc[0]),
        "final_fpr_pct": float(metrics_df.loc[metrics_df.stage == "FTIEF Global Threat Intelligence", "fpr_pct"].iloc[0]),
        "final_auc": float(metrics_df.loc[metrics_df.stage == "FTIEF Global Threat Intelligence", "roc_auc"].iloc[0]),
        "total_runtime_seconds": float(total_runtime),
        "generated_plots": len(list(PLOT_DIR.glob("*.png")))
    }
    pd.DataFrame([final_summary]).to_csv(OUTPUT_DIR / "integrated_efficiency_summary.csv", index=False)
    with open(OUTPUT_DIR / "run_configuration.json", "w") as f:
        json.dump({
            "seed": SEED,
            "max_samples": MAX_SAMPLES,
            "test_size": TEST_SIZE,
            "casle_graph_features": CASLE_GRAPH_FEATURES,
            "egfc_selected_features": EGFC_SELECTED_FEATURES,
            "latent_dim": LATENT_DIM,
            "autoencoder_epochs": AUTOENCODER_EPOCHS,
            "hcds_epochs": HCDS_EPOCHS,
            "fusion_epochs": FUSION_EPOCHS,
            "fgsm_epsilon": FGSM_EPSILON,
            "federated_clients": FED_CLIENTS,
            "federated_rounds": FED_ROUNDS,
            "local_epochs": LOCAL_EPOCHS,
            "batch_size": BATCH_SIZE
        }, f, indent=2)

    print("\nIntegrated stage metrics:")
    print(metrics_df.round(4).to_string(index=False))
    print("\nFinal efficiency summary:")
    print(pd.Series(final_summary).to_string())

    archive_path = shutil.make_archive(str(OUTPUT_DIR), "zip", root_dir=OUTPUT_DIR)
    print(f"\nAll outputs archived at: {archive_path}")
    print(f"All CSV files: {OUTPUT_DIR}")
    print(f"All model files: {OUTPUT_DIR}")
    print(f"All plots: {PLOT_DIR}")


def main():
    overall_start = time.perf_counter()
    banner("CAUSALITY-DRIVEN HYBRID INTRUSION DETECTION WITH ENTROPY-OPTIMIZED FEATURE LEARNING AND FEDERATED THREAT INTELLIGENCE")
    print(f"TensorFlow version: {tf.__version__}")
    print(f"Execution device(s): {tf.config.list_physical_devices()}")
    print(f"Output directory: {OUTPUT_DIR}")

    X_raw, y, attack_types = load_real_dataset()
    idx_train, idx_test = train_test_split(
        np.arange(len(y)), test_size=TEST_SIZE, stratify=y, random_state=SEED
    )
    raw_train = X_raw.iloc[idx_train].reset_index(drop=True)
    raw_test = X_raw.iloc[idx_test].reset_index(drop=True)
    y_train = y[idx_train]
    y_test = y[idx_test]

    preprocessor, numeric_cols, categorical_cols = build_preprocessor(raw_train.copy())
    raw_train_proc = raw_train.copy()
    raw_test_proc = raw_test.copy()
    for c in numeric_cols:
        raw_train_proc[c] = pd.to_numeric(raw_train_proc[c], errors="coerce").fillna(0.0)
        raw_test_proc[c] = pd.to_numeric(raw_test_proc[c], errors="coerce").fillna(0.0)

    preprocess_start = time.perf_counter()
    X_train = preprocessor.fit_transform(raw_train_proc).astype(np.float32)
    X_test = preprocessor.transform(raw_test_proc).astype(np.float32)
    preprocess_latency = 1000 * (time.perf_counter() - preprocess_start) / len(y)
    feature_names = preprocessor.get_feature_names_out().astype(str)

    print(f"Training samples: {len(y_train):,}")
    print(f"Test samples: {len(y_test):,}")
    print(f"Categorical inputs: {categorical_cols}")
    print(f"Numerical inputs: {len(numeric_cols)}")
    print(f"Encoded dimensions: {X_train.shape[1]}")
    print(f"Preprocessing latency: {preprocess_latency:.6f} ms/sample")
    pd.DataFrame({"feature": feature_names}).to_csv(OUTPUT_DIR / "encoded_feature_names.csv", index=False)

    casle = casle_fit_transform(X_train, X_test, y_train, raw_train_proc, raw_test_proc, feature_names)
    egfc = egfc_fit_transform(casle, y_train, y_test)
    hcds = hcds_fit(casle, egfc, y_train, y_test)
    arcm = arcm_calibrate(hcds, egfc, casle, y_train, y_test)
    ftief = ftief_train(egfc, hcds, arcm, y_train, y_test)

    total_runtime = time.perf_counter() - overall_start
    final_evaluation(y_train, y_test, casle, egfc, hcds, arcm, ftief, total_runtime)
    banner("PIPELINE COMPLETED SUCCESSFULLY")


if __name__ == "__main__":
    main()

