def main():
    overall_start = time.perf_counter()
    banner("CAUSALITY-DRIVEN HYBRID INTRUSION DETECTION WITH ENTROPY-OPTIMIZED FEATURE LEARNING AND FEDERATED THREAT INTELLIGENCE")
    print(f"TensorFlow version: {tf.__version__}")
    print(f"Execution device(s): {tf.config.list_physical_devices()}")
    print(f"Output directory: {OUTPUT_DIR}")

    X_raw, y, attack_types = load_real_dataset()
    idx_train, idx_test = train_test_split(
        np.arange(len(y)), test_size=TEST_SIZE, stratify=y, random_state=SEED
    )
    raw_train = X_raw.iloc[idx_train].reset_index(drop=True)
    raw_test = X_raw.iloc[idx_test].reset_index(drop=True)
    y_train = y[idx_train]
    y_test = y[idx_test]
    attack_types_test = attack_types.iloc[idx_test].reset_index(drop=True)

    preprocessor, numeric_cols, categorical_cols = build_preprocessor(raw_train.copy())
    raw_train_proc = raw_train.copy()
    raw_test_proc = raw_test.copy()
    for c in numeric_cols:
        raw_train_proc[c] = pd.to_numeric(raw_train_proc[c], errors="coerce").fillna(0.0)
        raw_test_proc[c] = pd.to_numeric(raw_test_proc[c], errors="coerce").fillna(0.0)

    preprocess_start = time.perf_counter()
    X_train = preprocessor.fit_transform(raw_train_proc).astype(np.float32)
    X_test = preprocessor.transform(raw_test_proc).astype(np.float32)
    preprocess_latency = 1000 * (time.perf_counter() - preprocess_start) / len(y)
    feature_names = preprocessor.get_feature_names_out().astype(str)

    print(f"Training samples: {len(y_train):,}")
    print(f"Test samples: {len(y_test):,}")
    print(f"Categorical inputs: {categorical_cols}")
    print(f"Numerical inputs: {len(numeric_cols)}")
    print(f"Encoded dimensions: {X_train.shape[1]}")
    print(f"Preprocessing latency: {preprocess_latency:.6f} ms/sample")
    pd.DataFrame({"feature": feature_names}).to_csv(OUTPUT_DIR / "encoded_feature_names.csv", index=False)

    casle = casle_fit_transform(X_train, X_test, y_train, raw_train_proc, raw_test_proc, feature_names)
    egfc = egfc_fit_transform(casle, y_train, y_test)
    hcds = hcds_fit(casle, egfc, y_train, y_test)
    arcm = arcm_calibrate(hcds, egfc, casle, y_train, y_test)
    ftief = ftief_train(egfc, hcds, arcm, y_train, y_test)

    total_runtime = time.perf_counter() - overall_start
    final_evaluation(y_train, y_test, casle, egfc, hcds, arcm, ftief, total_runtime)

    global UI_STATE
    UI_STATE = {
        "preprocessor": preprocessor,
        "numeric_cols": numeric_cols,
        "categorical_cols": categorical_cols,
        "raw_reference": raw_test_proc,
        "reference_labels": y_test,
        "reference_attack_types": attack_types_test,
        "casle": casle,
        "egfc": egfc,
        "hcds": hcds,
        "arcm": arcm,
        "ftief": ftief
    }
    banner("PIPELINE COMPLETED SUCCESSFULLY | ANALYTICAL UI READY")
    ui_started = launch_gradio_analytical_ui(UI_STATE)
    if not ui_started:
        launch_analytical_ui(UI_STATE)


if __name__ == "__main__":
    main()

