def banner(text):
    print("\n" + "=" * 118)
    print(text)
    print("=" * 118)


def normalize_column_name(name):
    s = str(name).strip().lower()
    s = re.sub(r"[^a-z0-9]+", "_", s)
    return re.sub(r"_+", "_", s).strip("_")


def normalize_columns(df):
    out = df.copy()
    out.columns = [normalize_column_name(c) for c in out.columns]
    return out.loc[:, ~out.columns.duplicated()]


def download_file(urls, destination, min_bytes=1024):
    destination = Path(destination)
    if destination.exists() and destination.stat().st_size >= min_bytes:
        print(f"[CACHE] {destination.name} ({destination.stat().st_size / 1e6:.1f} MB)")
        return destination
    last_error = None
    for url in urls:
        try:
            print(f"[DOWNLOAD] {url}")
            with requests.get(url, stream=True, timeout=(20, 180), allow_redirects=True, verify=False) as response:
                response.raise_for_status()
                total = int(response.headers.get("content-length", 0))
                downloaded = 0
                with open(destination, "wb") as f:
                    for chunk in response.iter_content(chunk_size=1024 * 1024):
                        if chunk:
                            f.write(chunk)
                            downloaded += len(chunk)
                            if total and downloaded % (25 * 1024 * 1024) < len(chunk):
                                print(f"  {100 * downloaded / total:5.1f}% | {downloaded / 1e6:.1f} MB")
            if destination.stat().st_size < min_bytes:
                raise IOError("Downloaded file is unexpectedly small")
            return destination
        except Exception as exc:
            last_error = exc
            print(f"[WARN] Download attempt failed: {exc}")
            if destination.exists():
                destination.unlink()
    raise RuntimeError(f"Unable to download {destination.name}: {last_error}")


def discover_iot23_labeled_url(scenario):
    directory_url = urljoin(IOT23_BASE, scenario + "/")
    response = requests.get(directory_url, timeout=60, verify=False)
    response.raise_for_status()
    matches = re.findall(r'href="([^"]*zeek-conn-log\.labeled)"', response.text, flags=re.I)
    if not matches:
        matches = re.findall(r'href="([^"]*conn[^\"]*\.labeled)"', response.text, flags=re.I)
    if not matches:
        raise RuntimeError(f"No labelled Zeek connection file found for {scenario}")
    return urljoin(directory_url, matches[0])


def download_iot23_scenarios():
    target_dir = DATA_DIR / "IoT23"
    target_dir.mkdir(parents=True, exist_ok=True)
    paths = []
    for scenario in IOT23_SCENARIOS:
        try:
            url = discover_iot23_labeled_url(scenario)
            filename = scenario + "_zeek_conn.log.labeled"
            path = download_file([url], target_dir / filename, min_bytes=1000)
            paths.append(path)
        except Exception as exc:
            print(f"[WARN] IoT-23 scenario {scenario} was not downloaded: {exc}")
    if len(paths) < 2:
        raise RuntimeError("Insufficient IoT-23 captures were downloaded")
    return paths


